const TIME_LIMIT: int = 1400;
const TH18_BALL: int = 416;

xformdef VELOCITY_RAMP(target_speed: fx, shot_angle: angle) {
    set_gravity(((target_speed - 1fx) / 90fx) * cos(shot_angle),
        ((target_speed - 1fx) / 90fx) * sin(shot_angle));
    @90 add_speed(0fx);
    set_gravity(0fx, 0fx);
}

async sub emitter(rank: int) {
    wait(60);
    for volley in 0..10 {
        var count: int = 6;
        var target_speed: fx = 2.3fx;
        if rank == 1 { count = 12; target_speed = 3.6fx; }
        if rank == 2 { count = 16; target_speed = 4fx; }
        if rank == 3 { count = 28; target_speed = 4.2fx; }

        // Source RANDRAD is consumed once per volley and shared by the whole ring.
        var phase: angle = rand(65536) as angle;
        for i in 0..count {
            var shot_angle: angle = phase + ((i * 65536 / count) as angle);
            var x: fx = $self_x - 4fx * cos(shot_angle);
            var y: fx = $self_y - 4fx * sin(shot_angle);
            _ = fire(TH18_BALL, 2, x, y, 1fx, shot_angle,
                VELOCITY_RAMP(target_speed, shot_angle), none);
        }
        if volley < 9 { wait(34); }
    }
}

async sub girl_d02(rank: int, phase_owner: int) {
    set_hurtbox(16fx);
    set_hitbox(12fx);
    set_invuln(65535);
    if phase_owner == 1 { phase_begin(0, none, TIME_LIMIT - 120, 0); }
    move_vel(0, 90deg, 3fx, EASE_LINEAR);
    move_vel(60, 90deg, 0fx, EASE_QUAD_IN);
    spawn emitter(rank);
    wait(400);
    move_vel(120, 90deg, 2fx, EASE_QUAD_IN);
    wait(60);
    loop { wait(1); }
}

sub main() {
    wait(120);
    var rank: int = global(GVAR_RANK);
    _ = spawn_enemy(64fx, -48fx, 2000, 0, 1000, 2, girl_d02(rank, 1));
    _ = spawn_enemy(-64fx, -48fx, 2000, 0, 1000, 2, girl_d02(rank, 0));
    loop { wait(1); }
}
